contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticketAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticketAmount)); require(ticketAmount <= 1000000000000000000000000000000);
        require(ticketAmount == 10, "ticket must be exactly 10 wei");
        require(address(this).balance >= ticketAmount, "insufficient test balance");

        uint preC = address(c).balance;
        uint preBank = c.bank().balance;
        bool reverted;

        c.play{value: ticketAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint postC = address(c).balance;
        uint postBank = c.bank().balance;

        assert(reverted || postC + postBank >= preC + preBank - ticketAmount);
    }

    receive() external payable {}
}

