// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticketAmount) internal {
        ticketAmount = bound(ticketAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticketAmount = 10;
        vm.assume(address(this).balance >= ticketAmount);
        uint preC = address(c).balance;
        uint preBank = c.bank().balance;
        bool reverted;
        try c.play{value: ticketAmount}() { reverted = false; } catch { reverted = true; }
        uint postC = address(c).balance;
        uint postBank = c.bank().balance;
        assertTrue(reverted || postC + postBank >= preC + preBank - ticketAmount);
    }

    function testFuzz_run(uint256 ticketAmount) public {
        _run(ticketAmount);
    }

    receive() external payable {}
}
